@Composable fun LiveCategoryConfigurationView(m:AppModel,close:()->Unit){
 val access=remember{m.priorityAccessKey};val version=remember{m.workspaceVersion};var row by remember{mutableStateOf<JSONObject?>(null)};var create by remember{mutableStateOf(false)};var proposed by remember{mutableStateOf<LiveCommand?>(null)};var error by remember{mutableStateOf("")}
 LaunchedEffect(m.priorityAccessKey,m.workspaceVersion){if(access!=m.priorityAccessKey||version!=m.workspaceVersion)close()}
 if(access!=m.priorityAccessKey||version!=m.workspaceVersion)return
 Dialog(onDismissRequest=close,properties=DialogProperties(usePlatformDefaultWidth=false)){Surface(Modifier.fillMaxSize(),color=Paper){LazyColumn(Modifier.safeDrawingPadding().imePadding().padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
  item{Row{Text("菜单分类",Modifier.weight(1f),style=MaterialTheme.typography.titleLarge);TextButton(onClick=close){Text("关闭")}};LivePendingView(m);TextButton(onClick={row=null;create=false;m.loadProducts()},enabled=!m.busy){Text("刷新分类")};SecondaryAction(onClick={row=null;create=true},enabled=m.canUseProducts&&m.productBoard?.configurable==true){Text("新增分类")};Text(error,color=MaterialTheme.colorScheme.error)}
  m.productBoard?.let{b->
   if(create||row!=null)item{key(row?.getString("id")?:"new",row?.getString("updatedAt")){CategoryFields(b,row){body->try{proposed=categoryConfigurationCommand(m.identity!!,b,row,body);error=""}catch(e:Exception){error=e.message.orEmpty()}}}}
   for(c in b.categories)item{Panel{Text(c.getString("displayName"),style=MaterialTheme.typography.titleMedium);Text("${c.getString("code")} · ${c.textOrNull("parentCode")?:"一级分类"} · ${c.getInt("productCount")}个商品");Text("排序${c.getInt("sortOrder")} · ${if(c.getBoolean("guestVisible"))"显示" else "隐藏"}");TextButton(onClick={row=c;create=false},enabled=m.canUseProducts){Text("编辑")}}}
  }
 }}}
 proposed?.let{c->AlertDialog(onDismissRequest={proposed=null},title={Text(c.title)},text={Text(c.steps[0].categoryConfigurationProof!!.getString("confirmation"))},confirmButton={TextButton(onClick={proposed=null;row=null;create=false;m.executeLive(c)},enabled=m.canExecuteLive(c)){Text("确认保存")}},dismissButton={TextButton(onClick={proposed=null}){Text("返回")}})}
}
@Composable private fun CategoryFields(b:ProductManagementBoard,row:JSONObject?,submit:(JSONObject)->Unit){
 var code by remember{mutableStateOf(row?.getString("code")?:"")};var name by remember{mutableStateOf(row?.getString("displayName")?:"")};var parent by remember{mutableStateOf(row?.textOrNull("parentCode")?:"")};var sort by remember{mutableStateOf((row?.getInt("sortOrder")?:100).toString())};var visible by remember{mutableStateOf(row?.getBoolean("guestVisible")?:true)}
 Panel{if(row==null)CustodyField("唯一分类编号",code,64){code=it};CustodyField("分类名称",name,32){name=it};AssignmentChoice("上级分类",parent,listOf("" to "无（一级分类）")+b.categories.filter{it.textOrNull("parentCode")==null&&it.getString("code")!=code}.map{it.getString("code") to it.getString("displayName")}){parent=it};CustodyField("排序",sort,6){sort=it};Row{Checkbox(visible,{visible=it});Text("客人菜单显示")};SecondaryAction(onClick={val body=JSONObject().put("displayName",name.trim()).put("parentCode",parent.ifBlank{null}?:JSONObject.NULL).put("sortOrder",sort.toIntOrNull()?:-1).put("guestVisible",visible);if(row==null)body.put("code",code.trim());submit(body)}){Text("核对分类")}}
}
