 if(productImagePicker)LiveMediaAssetPicker(m,"menu",{productImagePicker=false}){imageUrl=it;productImagePicker=false}
 var newCode by remember{mutableStateOf(p.optString("suggestedCode",""))};var newPrice by remember{mutableStateOf("")};val creating=p.getString("id")=="new"
