 LaunchedEffect(m.priorityAccessKey,m.workspaceVersion){if(access!=m.priorityAccessKey||version!=m.workspaceVersion)close()};if(access!=m.priorityAccessKey||version!=m.workspaceVersion)return
 Dialog(onDismissRequest=close,properties=DialogProperties(usePlatformDefaultWidth=false)){Surface(Modifier.fillMaxSize(),color=Paper){LazyColumn(Modifier.safeDrawingPadding().imePadding().padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
  item{Row{Text("商品与套餐配置",Modifier.weight(1f),style=MaterialTheme.typography.titleLarge);TextButton(onClick=close){Text("关闭")}};Text(p.getString("code"));if(creating){CustodyField("唯一商品编号",newCode,64){newCode=it};CustodyField("初始售价（元，可留空后设置）",newPrice,12){newPrice=it};Text("新商品先以未上架保存，完成配方、成本和售价核对后再上架。")}
   CustodyField("商品名称",name,160){name=it};CustodyField("商品介绍",description,2000){description=it};if(imageUrl.isNotBlank()){Text("已选择商品图片");imageUrl.substringAfterLast('/').takeIf{Regex("^MA[0-9A-F]{32}$").matches(it)}?.let{MediaAssetThumbnail(m,it)}};if(m.identity?.allows("media.asset.menu.manage")==true)Row{TextButton(onClick={productImagePicker=true}){Text("选择或上传商品图")};if(imageUrl.isNotBlank())TextButton(onClick={imageUrl=""}){Text("移除商品图")}};AssignmentChoice("二级菜单分类",category,m.productBoard?.categories?.filter{it.textOrNull("parentCode")!=null}?.map{it.getString("code") to it.getString("displayName")}?:emptyList()){category=it};AssignmentChoice("商品类型",kind,listOf("single" to "单品","bundle" to "套餐")){kind=it};AssignmentChoice("出品位置",station,listOf("bar" to "吧台","kitchen" to "厨房","cashier" to "收银","none" to "无需制作")){station=it};AssignmentChoice("库存控制",mode,listOf("tracked" to "按配方跟踪库存","not_managed" to "不管理库存")){mode=it};Text("更改库存模式和套餐构成会影响后续成本与备料；已下单商品保持原快照。套餐成本由组成商品计算。")
   CustodyField("单次最大数量",max,4){max=it};CustodyField("供应开始（HH:mm，可留空）",from,5){from=it};CustodyField("供应结束（HH:mm，可留空）",until,5){until=it};for((code,label) in listOf("guest_qr" to "顾客扫码","staff_assisted" to "员工点单","cashier" to "收银","reservation" to "预约","integration" to "外部接入"))Row{Checkbox(code in channels,{checked->channels=if(checked)(channels+code).distinct() else channels-code});Text(label)}
  }
  if(kind=="bundle"){
   item{Text("固定组成",style=MaterialTheme.typography.titleMedium);SecondaryAction(onClick={selectedGroup=-1;picker=true}){Text("添加固定单品")}}
   for((i,c) in components.withIndex())item{Panel{Text(c.optString("name",c.getString("productId")));CustodyField("份数",c.getInt("quantity").toString(),3){v->components=components.mapIndexed{j,r->if(i==j)JSONObject(r.toString()).put("quantity",v.toIntOrNull()?:0) else r}};CustodyField("备注",c.textOrNull("note")?:"",500){v->components=components.mapIndexed{j,r->if(i==j)JSONObject(r.toString()).put("note",v.ifBlank{null}?:JSONObject.NULL) else r}};TextButton(onClick={components=components.filterIndexed{j,_->j!=i}}){Text("移除")}}}
   item{Text("自选组",style=MaterialTheme.typography.titleMedium);SecondaryAction(onClick={groups=groups+JSONObject().put("code","choice_${java.util.UUID.randomUUID().toString().take(8)}").put("name","自选组${groups.size+1}").put("selectionCount",1).put("sortOrder",(groups.size+1)*10).put("options",JSONArray())},enabled=groups.size<20){Text("新增自选组")}}
   for((i,g) in groups.withIndex())item{Panel{CustodyField("组名称",g.getString("name"),80){v->groups=groups.mapIndexed{j,r->if(i==j)JSONObject(r.toString()).put("name",v) else r}};CustodyField("每套选几种",g.getInt("selectionCount").toString(),2){v->groups=groups.mapIndexed{j,r->if(i==j)JSONObject(r.toString()).put("selectionCount",v.toIntOrNull()?:0) else r}};for((oi,o) in g.getJSONArray("options").objects().withIndex()){Text(o.optString("productName",o.optString("name",o.getString("productId"))));CustodyField("选中后份数",o.getInt("quantity").toString(),3){v->groups=groups.mapIndexed{j,r->if(i==j)JSONObject(r.toString()).put("options",JSONArray(r.getJSONArray("options").objects().mapIndexed{oj,x->if(oi==oj)JSONObject(x.toString()).put("quantity",v.toIntOrNull()?:0) else x})) else r}};TextButton(onClick={groups=groups.mapIndexed{j,r->if(i==j)JSONObject(r.toString()).put("options",JSONArray(r.getJSONArray("options").objects().filterIndexed{oj,_->oi!=oj})) else r}}){Text("移除此候选")}}
    Row{TextButton(onClick={selectedGroup=i;picker=true}){Text("添加候选单品")};TextButton(onClick={groups=groups.filterIndexed{j,_->j!=i}}){Text("删除自选组")}}
   }}
  }
  item{Text(notice,color=MaterialTheme.colorScheme.error);PrimaryAction(onClick={try{require(channels.isNotEmpty()){ "至少选择一个销售渠道" };require((from.isBlank()&&until.isBlank())||(Regex("^(?:[01]\\d|2[0-3]):[0-5]\\d$").matches(from)&&Regex("^(?:[01]\\d|2[0-3]):[0-5]\\d$").matches(until))){"供应时间须成对填写HH:mm"};val patch=JSONObject().put("productSnapshot",JSONObject((p.optJSONObject("productSnapshot")?:JSONObject()).toString()).put("description",description.trim()).put("imageUrl",imageUrl)).put("name",name.trim()).put("categoryCode",category).put("productKind",kind).put("fulfillmentStation",station).put("inventoryControlMode",mode).put("maxOrderQuantity",max.toIntOrNull()?:0).put("availableFrom",from.ifBlank{null}?:JSONObject.NULL).put("availableUntil",until.ifBlank{null}?:JSONObject.NULL).put("allowedChannels",JSONArray(channels));val clean:(JSONObject)->JSONObject={r->JSONObject(r.toString()).also{it.remove("name");it.remove("productName");it.remove("available");it.remove("productCode");it.remove("fulfillmentStation");it.remove("status")}};patch.put("bundleComponents",JSONArray(if(kind=="bundle")components.map(clean) else emptyList<JSONObject>())).put("bundleChoiceGroups",JSONArray(if(kind=="bundle")groups else emptyList<JSONObject>()));if(creating){patch.put("code",newCode.trim()).put("status","inactive");if(newPrice.isNotBlank()){require(m.productBoard?.canPrice==true){"设置初始售价需要价格管理权"};patch.put("standardPrice",JSONObject().put("amountMinor",ownerMoney(newPrice)).put("currency","CNY").put("reason","原生创建商品初始售价"))}};proposed=productConfigurationCommand(m.identity!!,m.productBoard!!,p,patch,"${if(creating)"新建未上架商品 $newCode" else "配置商品"} $name\n${if(creating)"初始售价：${newPrice.ifBlank{"未配置"}}\n" else ""}分类：${m.productBoard!!.categories.find{it.getString("code")==category}?.getString("displayName")}\n${if(kind=="bundle")"套餐：${components.size}个固定单品、${groups.size}个自选组" else "单品"}\n供应：${if(from.isBlank())"全天" else "$from 至 $until"}\n最大数量：$max\n库存：${if(mode=="tracked")"配方跟踪" else "