 }}}
 if(picker)ProductConfigurationPicker(m,p.getString("id"),close={picker=false}){r->val c=JSONObject().put("productId",r.getString("id")).put("name",r.getString("name")).put("quantity",1).put("sortOrder",10);if(selectedGroup<0){if(components.none{it.getString("productId")==r.getString("id")})components=components+c.put("sortOrder",(components.size+1)*10)}else groups=groups.mapIndexed{i,g->if(i==selectedGroup&&g.getJSONArray("options").objects().none{it.getString("productId")==r.getString("id")})JSONObject(g.toString()).put("options",JSONArray(g.getJSONArray("options").objects()+c.put("sortOrder",(g.getJSONArray("options").length()+1)*10))) else g};picker=false}
 proposed?.let{c->AlertDialog(onDismissRequest={proposed=null},title={Text(c.title)},text={Text(c.steps[0].productManagementProof!!.getString("confirmation"))},confirmButton={TextButton(onClick={proposed=null;m.executeLive(c);close()},enabled=m.canExecuteLive(c)){Text("确认保存")}},dismissButton={TextButton(onClick={proposed=null}){Text("返回")}})}
