@Composable fun ProductConfigurationPicker(m:AppModel,exclude:String,singleOnly:Boolean=true,close:()->Unit,choose:(JSONObject)->Unit){var query by remember{mutableStateOf("")};var rows by remember{mutableStateOf(emptyList<JSONObject>())};var offset by remember{mutableStateOf(0)};var loading by remember{mutableStateOf(false)};var error by remember{mutableStateOf("")};val scope=rememberCoroutineScope();fun load(page:Int){if(loading)return;scope.launch{loading=true;try{rows=m.queryProductConfigurationChoices(query,page,singleOnly).filter{it.getString("id")!=exclude};offset=page;error=""}catch(e:Exception){rows=emptyList();error=e.message.orEmpty()}finally{loading=false}}};LaunchedEffect(Unit){load(0)}
 Dialog(onDismissRequest=close,properties=DialogProperties(usePlatformDefaultWidth=false)){Surface(Modifier.fillMaxSize(),color=Paper){LazyColumn(Modifier.safeDrawingPadding().imePadding().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text(if(singleOnly)"选择原门店单品" else "选择原门店商品",style=MaterialTheme.typography.titleLarge);CustodyField("搜索名称或编码",query,80){query=it};Row{TextButton(onClick={load(0)},enabled=!loading){Text("查询")};TextButton(onClick=close){Text("关闭")}};Text(error)};for(r in rows)item{SecondaryAction(onClick={choose(r)}){Text("${r.getString("name")} · ${r.getString("code")}")}};item{Row{TextButton(onClick={load((offset-50).coerceAtLeast(0))},enabled=!loading&&offset>0){Text("上一页")};TextButton(onClick={load(offset+50)},enabled=!loading&&offset<10000){Text("下一页")}};if(rows.isEmpty())Text("本页没有可选单品，可继续翻页或更改搜索")}}}}
}
